using Microsoft.EntityFrameworkCore;
using Shuffull.Core.Models.Dtos;
using System.ComponentModel.DataAnnotations;

namespace Shuffull.Core.Models.Database;

/// <summary>
/// A saved Genre Jam: a named set of shuffle filters over the user's whole library (shuffull-workspace#137). The app
/// builds and plays it locally; this row is what lets a jam saved on one device show up on the user's others.
///
/// <para><see cref="GenreJamId"/> is generated by the app when the jam is first saved, so the app's outbox can
/// create and later replace it with the same <c>PUT</c>, and a resend changes nothing.</para>
///
/// <para>The filters are stored as JSON (see <see cref="GenreJamFilters"/>). Nothing on the server filters by them:
/// the app runs the jam against its own copy of the library.</para>
/// </summary>
[Index(nameof(UserId))]
public class GenreJam
{
    public const int MaxIdLength = 64;
    public const int MaxNameLength = 100;

    [Key, MaxLength(MaxIdLength)]
    public string GenreJamId { get; set; }

    [Required]
    public string UserId { get; set; }

    [Required, MaxLength(MaxNameLength)]
    public string Name { get; set; }

    /// <summary>What the jam keeps to: a song must match each non-empty list.</summary>
    [Required]
    public GenreJamFilters Whitelists { get; set; }

    /// <summary>What the jam leaves out.</summary>
    [Required]
    public GenreJamFilters Blacklists { get; set; }

    /// <summary>The heaviness band, 1-10, both bounds included. Null means any.</summary>
    public int? HeavinessMin { get; set; }

    public int? HeavinessMax { get; set; }

    /// <summary>When the jam was last saved.</summary>
    [Required]
    public DateTime Version { get; set; }

    public User User { get; set; }
}
